#!/usr/bin/env node
// Current Core distribution and guarded catalog refresh. Historical migration200
// is an immutable predecessor input, never an output. A changed accepted368 also
// refuses regeneration: later section changes require their own forward migration.
import {readFileSync,writeFileSync,mkdirSync,existsSync} from 'node:fs';
import {dirname,resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {createLetbuyyCoreLiquidThemeBundleFixture,LETBUYY_CORE_STARTER_ANNOUNCEMENT} from '../../packages/theme-engine/src/theme-bundle-core.ts';
import {getExperience,buildExperienceSettingsOverlay} from '../../packages/theme-engine/src/theme-presets.ts';
import {LiquidThemePackageBundleSchema} from '../../packages/theme-engine/src/theme-bundle.ts';
if(process.argv.slice(2).some(arg=>arg!=='--check'))throw new Error('Supported option: --check');
const check=process.argv.includes('--check');
const root=resolve(dirname(fileURLToPath(import.meta.url)),'../..');
const historical=readFileSync(resolve(root,'database/supabase/migrations/200_letbuyy_core_liquid_bundle_attach.sql'),'utf8');
const match=historical.match(/\$liquidbundle\$([\s\S]*?)\$liquidbundle\$/);
if(!match)throw new Error('Historical Core bundle is unavailable');
// Migration367 corrects the starter sentence before this migration runs.
const before=LiquidThemePackageBundleSchema.parse(JSON.parse(match[1].replaceAll('Free shipping on fresh drops this week.',LETBUYY_CORE_STARTER_ANNOUNCEMENT)));
// This generator reproduces accepted migration 368 and its frozen seed. Later
// source changes require a new forward migration; Wave 6's public-contact
// footer must not be silently folded into the already accepted section set.
const current=createLetbuyyCoreLiquidThemeBundleFixture();
const after={...current,sections:{...current.sections,footer:before.sections.footer}};
const stable=value=>JSON.stringify(value,(_key,item)=>item&&typeof item==='object'&&!Array.isArray(item)?Object.fromEntries(Object.entries(item).sort(([a],[b])=>a.localeCompare(b))):item);
const changed=Object.keys(after.sections).filter(key=>stable(before.sections[key])!==stable(after.sections[key]));
if(changed.length!==13)throw new Error('Core refresh scope changed; prepare a new reviewed forward migration');
const approvedStarter=getExperience('sense');
const declaredKeys=new Set(Object.values(after.config.settings_schema.settings).flatMap(group=>Object.keys(group.fields)));
const approvedPreset=Object.fromEntries(Object.entries(buildExperienceSettingsOverlay(approvedStarter)).filter(([key])=>declaredKeys.has(key)));
const priorPresets=before.config.settings_data.presets,currentPresets=after.config.settings_data.presets;
if(!priorPresets.Sense || currentPresets.Sense || stable(currentPresets.Threadline)!==stable(approvedPreset)
 || stable(Object.keys(priorPresets).filter(key=>key!=='Sense'))!==stable(Object.keys(currentPresets).filter(key=>key!=='Threadline')))
 throw new Error('Unexpected starter preset drift');
const comparable={...after,config:{...after.config,settings_data:{...after.config.settings_data,presets:priorPresets}}};
if(stable({...before,sections:{}})!==stable({...comparable,sections:{}}))throw new Error('Unexpected non-section Core drift');
const changes=Object.fromEntries(changed.sort().map(key=>[key,{before:before.sections[key],after:after.sections[key]}]));
function sql(rollback){
 const data=rollback?Object.fromEntries(Object.entries(changes).map(([key,row])=>[key,{before:row.after,after:row.before}])):changes;
 const payload=JSON.stringify(data);if(payload.includes('$coresections$'))throw new Error('Unsafe migration delimiter');
 return `-- 368 — Current canonical Core section definitions (${rollback?'rollback':'forward'}).
-- Generated by scripts/liquid-parity/build-letbuyy-core-bundle.mjs.
-- Only known unowned first-party catalog definitions change. Existing sites,
-- drafts and immutable releases are unchanged; owners publish upgrades explicitly.
-- Validate every selected section before mutation. Unknown definitions refuse;
-- the exact before/after states allow harmless repeated application.
DO $refresh$
DECLARE
  changes jsonb := $coresections$${payload}$coresections$::jsonb;
  original jsonb;
  bundle jsonb;
  entry record;
BEGIN
  SELECT default_template INTO original FROM public.themes
   WHERE slug='letbuyy-core' AND owned_by_site_id IS NULL
     AND NOT COALESCE(is_site_private,false) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unowned canonical Core catalog is unavailable'; END IF;
  bundle := original->'liquidBundle';
  IF bundle#>>'{package,slug}' IS DISTINCT FROM 'letbuyy-core-liquid'
     OR bundle#>>'{renderer,engine}' IS DISTINCT FROM 'liquid' THEN
    RAISE EXCEPTION 'Unexpected Core package or renderer';
  END IF;
  FOR entry IN SELECT key,value FROM jsonb_each(changes) LOOP
    IF bundle#>ARRAY['sections',entry.key] IS DISTINCT FROM entry.value->'before'
       AND bundle#>ARRAY['sections',entry.key] IS DISTINCT FROM entry.value->'after' THEN
      RAISE EXCEPTION 'Unexpected Core catalog section: %',entry.key;
    END IF;
  END LOOP;
  FOR entry IN SELECT key,value FROM jsonb_each(changes) LOOP
    bundle := jsonb_set(bundle,ARRAY['sections',entry.key],entry.value->'after',false);
  END LOOP;
  IF bundle IS DISTINCT FROM original->'liquidBundle' THEN
    UPDATE public.themes SET default_template=jsonb_set(original,'{liquidBundle}',bundle,false),updated_at=NOW()
      WHERE slug='letbuyy-core' AND owned_by_site_id IS NULL AND NOT COALESCE(is_site_private,false);
  END IF;
END
$refresh$;
`;
}
const outputs=[['database/supabase/migrations/368_core_section_catalog_refresh.sql',sql(false)],['database/supabase/rollback/368_core_section_catalog_refresh.rollback.sql',sql(true)]];
// Refuse historical drift before writing any artifact.
for(const[path,content]of outputs)if(existsSync(resolve(root,path))&&readFileSync(resolve(root,path),'utf8')!==content)throw new Error('Refusing to rewrite accepted migration '+path+'; add a new forward/rollback pair');
outputs.push(['database/supabase/seeds/generated/letbuyy-core-liquid-bundle.json',JSON.stringify(after,null,2)+'\n']);
for(const[path,content]of outputs){
 if(check){if(!existsSync(resolve(root,path))||readFileSync(resolve(root,path),'utf8')!==content)throw new Error('Generated Core artifact is stale: '+path);}
 else{mkdirSync(dirname(resolve(root,path)),{recursive:true});writeFileSync(resolve(root,path),content);}
}
console.info(JSON.stringify({coreSectionRefresh:changed.length,historicalMigrationRewritten:false,check,outputs:outputs.map(([path])=>path)}));
